describe('User Profile - Update Display Name', () => {
    beforeEach(() => {
        cy.visit('/profile');
        cy.login('testuser', 'password123'); // Assuming a login function exists
    });

    it('should update the display name successfully', () => {
        const newDisplayName = 'New Display Name';

        cy.get('input[name="displayName"]').clear().type(newDisplayName);
        cy.get('button[type="submit"]').click();

        cy.get('.notification').should('contain', 'Display name updated successfully');
        cy.get('.user-display-name').should('contain', newDisplayName);
    });

    it('should show an error message when the display name is empty', () => {
        cy.get('input[name="displayName"]').clear();
        cy.get('button[type="submit"]').click();

        cy.get('.error-message').should('contain', 'Display name cannot be empty');
    });
});
